"use client";

import { Button, Group, Text } from '@mantine/core';

import { randomId, useForceUpdate } from '@mantine/hooks';

function Demo() {
  const forceUpdate = useForceUpdate();

  return (
    <Group justify="center">
      <Text>{randomId()}</Text>
      <Button onClick={forceUpdate}>Force update</Button>
    </Group>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

"use client";

import { RendynExample as Example } from "@/components/rendyn-libraries/mantine/upstream/src/demos/hooks/use-force-update/use-force-update.demo.usage";
import { MantineProvider } from "@mantine/core";
import "@mantine/core/styles.css";

export default function Preview() {

  return <div style={{ width: "100%", maxWidth: "48rem", padding: "1.5rem" }}><MantineProvider><Example /></MantineProvider></div>;
}
